<style>
.shared-folder{max-width:1160px;margin:0 auto;padding:30px 20px 56px}.folder-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.folder-title-wrap{min-width:0}.folder-title-wrap h1{font-size:36px;margin:4px 0 3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.folder-sub{font:10px 'JetBrains Mono',monospace;color:var(--text-dim)}.folder-actions{display:flex;gap:8px;flex:none}.share-btn{display:inline-flex;align-items:center;justify-content:center;min-height:39px;padding:9px 14px;border-radius:7px;border:1px solid var(--hairline);background:var(--surface);color:var(--text-dim);font-size:12px;font-weight:700;text-decoration:none}.share-btn:hover{border-color:var(--cyan);color:var(--cyan)}.share-btn.primary{border-color:var(--cyan);background:var(--cyan);color:#061019}.crumbs{display:flex;gap:5px;align-items:center;overflow:auto;margin:0 0 14px;padding:4px 0}.crumb{flex:none;color:var(--text-dim);text-decoration:none;font-size:12px;padding:6px 8px;border-radius:5px}.crumb:hover,.crumb.current{color:var(--cyan);background:var(--surface-2)}.sep{color:#4f5a77}.summary{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px}.summary span{padding:7px 10px;border:1px solid var(--hairline);border-radius:20px;background:var(--surface);font:10px 'JetBrains Mono',monospace;color:var(--text-dim)}.section{margin-top:18px}.section-label{margin:0 0 9px;font:10px 'JetBrains Mono',monospace;text-transform:uppercase;letter-spacing:.12em;color:var(--text-dim)}.folder-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.folder-card{display:flex;align-items:center;gap:11px;padding:13px;border:1px solid var(--hairline);border-radius:8px;background:var(--surface-2);color:var(--text);text-decoration:none;min-width:0}.folder-card:hover{border-color:var(--cyan);transform:translateY(-1px)}.folder-icon{font-size:24px}.folder-copy{min-width:0}.folder-name{display:block;font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.folder-count{display:block;margin-top:3px;font:9px 'JetBrains Mono',monospace;color:var(--text-dim)}.file-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}.file-row{display:grid;grid-template-columns:48px minmax(0,1fr) auto;gap:12px;align-items:center;padding:11px 12px;border:1px solid var(--hairline);border-radius:8px;background:var(--surface-2)}.file-row:hover{border-color:#536b9f}.file-badge{width:46px;height:40px;display:grid;place-items:center;border:1px solid var(--hairline);border-radius:6px;background:var(--surface);font:700 9px 'JetBrains Mono',monospace;color:var(--cyan)}.file-copy{min-width:0}.file-title{font-size:14px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-name{margin-top:2px;font:10px 'JetBrains Mono',monospace;color:#7581a4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-meta{margin-top:5px;font:9px 'JetBrains Mono',monospace;color:var(--text-dim)}.file-actions{display:flex;gap:6px}.file-actions a{padding:8px 10px;border:1px solid var(--hairline);border-radius:6px;color:var(--text-dim);text-decoration:none;font-size:11px;font-weight:650}.file-actions a:hover{border-color:var(--cyan);color:var(--cyan)}.empty{padding:30px;border:1px dashed var(--hairline);border-radius:8px;text-align:center;color:var(--text-dim)}.share-note{margin-top:24px;padding:12px;border:1px solid rgba(95,217,232,.25);border-radius:8px;background:rgba(95,217,232,.06);font-size:11px;color:var(--text-dim);line-height:1.6}.download-status{display:none;margin-top:12px;padding:12px;border:1px solid var(--hairline);border-radius:8px;background:var(--surface)}.download-status.show{display:block}.progress-track{height:7px;border-radius:20px;background:var(--surface-2);overflow:hidden;margin:9px 0}.progress-bar{height:100%;width:0;background:var(--cyan);transition:width .12s}.download-copy{font:10px 'JetBrains Mono',monospace;color:var(--text-dim)}@media(max-width:800px){.folder-head{display:block}.folder-actions{margin-top:13px}.folder-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.shared-folder{padding:22px 13px 42px}.folder-title-wrap h1{font-size:30px}.folder-actions{display:grid;grid-template-columns:1fr}.folder-grid{grid-template-columns:1fr}.file-row{grid-template-columns:42px minmax(0,1fr)}.file-badge{width:40px}.file-actions{grid-column:1/-1;justify-content:flex-end}.file-actions a{flex:1;text-align:center}}
