<div class="twinkle-layer" id="twinkleLayer"></div>
<main class="shared-folder">
  <header class="folder-head">
    <div class="folder-title-wrap"><p class="eyebrow">Shared folder from Damon's Archive</p><h1><?= esc($currentName) ?></h1><div class="folder-sub"><?= esc($rootName) ?> · anyone with this link can view</div></div>
    <div class="folder-actions"><button type="button" class="share-btn primary" id="downloadFolderBtn" data-path="<?= esc($relativePath, 'attr') ?>" data-name="<?= esc($currentName, 'attr') ?>">Download folder</button></div>
  </header>

  <nav class="crumbs" aria-label="Shared folder breadcrumb">
    <?php foreach ($breadcrumbs as $index => $crumb): ?>
      <?php if ($index > 0): ?><span class="sep">/</span><?php endif; ?>
      <a class="crumb <?= $index === count($breadcrumbs) - 1 ? 'current' : '' ?>" href="<?= esc($folderUrl((string) $crumb['path']), 'attr') ?>"><?= esc($index === 0 ? $rootName : $crumb['label']) ?></a>
    <?php endforeach; ?>
  </nav>

  <div class="summary"><span><?= number_format((int) $summary['files']) ?> file<?= (int) $summary['files'] === 1 ? '' : 's' ?> in this folder tree</span><span><?= esc(ImportantFileModel::formatBytes((int) $summary['bytes'])) ?></span><?php if (! empty($share['expires_at'])): ?><span>Expires <?= esc(date('M j, Y', strtotime((string) $share['expires_at']))) ?></span><?php endif; ?></div>

  <div class="download-status" id="downloadStatus"><strong id="downloadTitle">Preparing folder…</strong><div class="progress-track"><div class="progress-bar" id="downloadBar"></div></div><div class="download-copy" id="downloadCopy">Creating secure download list…</div></div>

  <?php if ($folders !== []): ?><section class="section"><h2 class="section-label">Folders</h2><div class="folder-grid">
    <?php foreach ($folders as $folder): ?><a class="folder-card" href="<?= esc($folderUrl((string) $folder['relativePath']), 'attr') ?>"><span class="folder-icon">&#128193;</span><span class="folder-copy"><span class="folder-name"><?= esc($folder['name']) ?></span><span class="folder-count"><?= (int) $folder['count'] ?> item<?= (int) $folder['count'] === 1 ? '' : 's' ?></span></span></a><?php endforeach; ?>
  </div></section><?php endif; ?>

  <?php if ($files !== []): ?><section class="section"><h2 class="section-label">Files</h2><ul class="file-list">
    <?php foreach ($files as $file): $type = ImportantFileModel::typeLabel((string) $file['mime_type'], (string) $file['original_filename']); ?>
      <li class="file-row"><div class="file-badge"><?= esc($type) ?></div><div class="file-copy"><div class="file-title"><?= esc($file['title']) ?></div><div class="file-name"><?= esc($file['original_filename']) ?></div><div class="file-meta"><?= esc(ImportantFileModel::formatBytes((int) $file['file_size'])) ?> · <?= esc(date('M j, Y', strtotime((string) $file['created_at']))) ?></div></div><div class="file-actions"><a href="<?= esc(base_url('share/' . $token . '/file/' . $file['id']), 'attr') ?>">Open</a><a href="<?= esc(base_url('share/' . $token . '/file/' . $file['id'] . '/download'), 'attr') ?>">Download</a></div></li>
    <?php endforeach; ?>
  </ul></section><?php endif; ?>

  <?php if ($folders === [] && $files === []): ?><div class="empty">This shared folder is empty.</div><?php endif; ?>
  <div class="share-note">Only files inside the folder selected by the owner are available through this link. The rest of the website and vault remain private.</div>
</main>
