<script>
const button=document.getElementById('downloadFolderBtn'),statusBox=document.getElementById('downloadStatus'),statusTitle=document.getElementById('downloadTitle'),statusBar=document.getElementById('downloadBar'),statusCopy=document.getElementById('downloadCopy');
const ENCODER=new TextEncoder(),MAX32=0xffffffff,CRC_TABLE=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?(0xedb88320^(c>>>1)):(c>>>1);t[n]=c>>>0;}return t;})();
function crcUpdate(crc,bytes){let c=crc>>>0;for(let i=0;i<bytes.length;i++)c=(CRC_TABLE[(c^bytes[i])&255]^(c>>>8))>>>0;return c>>>0}function u16(v,o,x){v.setUint16(o,x&65535,true)}function u32(v,o,x){v.setUint32(o,x>>>0,true)}function dosDate(value){const d=value?new Date(value):new Date(),x=Number.isFinite(d.getTime())?d:new Date(),y=Math.max(1980,Math.min(2107,x.getFullYear()));return{time:((x.getHours()&31)<<11)|((x.getMinutes()&63)<<5)|(Math.floor(x.getSeconds()/2)&31),date:((y-1980)<<9)|(((x.getMonth()+1)&15)<<5)|(x.getDate()&31)}}
function localHeader(name,d){const o=new Uint8Array(30+name.length),v=new DataView(o.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x0808);u16(v,10,d.time);u16(v,12,d.date);u16(v,26,name.length);o.set(name,30);return o}function descriptor(crc,size){const o=new Uint8Array(16),v=new DataView(o.buffer);u32(v,0,0x08074b50);u32(v,4,crc);u32(v,8,size);u32(v,12,size);return o}function central(e){const o=new Uint8Array(46+e.name.length),v=new DataView(o.buffer);u32(v,0,0x02014b50);u16(v,4,20);u16(v,6,20);u16(v,8,0x0808);u16(v,12,e.d.time);u16(v,14,e.d.date);u32(v,16,e.crc);u32(v,20,e.size);u32(v,24,e.size);u16(v,28,e.name.length);u32(v,42,e.offset);o.set(e.name,46);return o}function end(count,size,offset){const o=new Uint8Array(22),v=new DataView(o.buffer);u32(v,0,0x06054b50);u16(v,8,count);u16(v,10,count);u32(v,12,size);u32(v,16,offset);return o}
async function* pieces(files,onProgress){const entries=[];let offset=0,loaded=0,done=0,total=files.reduce((s,f)=>s+(Number(f.size)||0),0);for(const file of files){const name=ENCODER.encode(file.name||'file'),d=dosDate(file.lastModified),start=offset,h=localHeader(name,d);yield h;offset+=h.length;let crc=0xffffffff,size=0;const response=await fetch(file.url,{cache:'no-store',credentials:'omit'});if(!response.ok)throw new Error('Could not download '+file.name);const reader=response.body?.getReader();if(reader){while(true){const part=await reader.read();if(part.done)break;const chunk=part.value;crc=crcUpdate(crc,chunk);size+=chunk.length;loaded+=chunk.length;offset+=chunk.length;if(size>MAX32||offset>MAX32)throw new Error('This ZIP is too large.');yield chunk;onProgress(loaded,total,done,files.length,file.name)}reader.releaseLock()}else{const chunk=new Uint8Array(await response.arrayBuffer());crc=crcUpdate(crc,chunk);size=chunk.length;loaded+=chunk.length;offset+=chunk.length;yield chunk}crc=(crc^0xffffffff)>>>0;const dd=descriptor(crc,size);yield dd;offset+=dd.length;entries.push({name,d,crc,size,offset:start});done++;onProgress(loaded,total,done,files.length,file.name)}const start=offset;for(const e of entries){const h=central(e);yield h;offset+=h.length}yield end(entries.length,offset-start,start)}
function zipStream(files,onProgress){const it=pieces(files,onProgress);return new ReadableStream({async pull(c){try{const r=await it.next();r.done?c.close():c.enqueue(r.value)}catch(e){c.error(e)}}})}function bytes(n){if(!n)return'0 B';const u=['B','KB','MB','GB'],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),3);return(n/1024**i).toFixed(i?1:0)+' '+u[i]}function safeName(n){return(String(n||'shared-folder.zip').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').trim()||'shared-folder.zip')}
button.addEventListener('click',async()=>{button.disabled=true;button.textContent='Preparing…';statusBox.classList.add('show');statusTitle.textContent='Preparing folder…';statusBar.style.width='0%';statusCopy.textContent='Creating secure download list…';try{const url=new URL(<?= json_encode(base_url('share/' . $token . '/folder-manifest')) ?>);if(button.dataset.path)url.searchParams.set('path',button.dataset.path);const response=await fetch(url,{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'Folder download failed.');const stream=zipStream(data.files,(loaded,total,done,count,name)=>{statusBar.style.width=(total?Math.min(98,Math.round(loaded/total*98)):Math.round(done/count*98))+'%';statusCopy.textContent=done+' / '+count+' files · '+bytes(loaded)+' / '+bytes(total)+' · '+name});const blob=await new Response(stream,{headers:{'Content-Type':'application/zip'}}).blob(),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=safeName(data.archiveName);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),60000);statusBar.style.width='100%';statusTitle.textContent='Folder downloaded';statusCopy.textContent=data.fileCount+' files · '+bytes(data.totalBytes)}catch(error){statusBar.style.width='0%';statusTitle.textContent='Download failed';statusCopy.textContent=error.message||'Could not download this folder.'}finally{button.disabled=false;button.textContent='Download folder'}});
</script>
</body>
